template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 80mm;
  height: 50mm;
  padding: 3mm 3.2mm 2.4mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
}
.price {
  font-size: 28px;
  font-weight: 800;
  margin-top: 1.8mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 14px;
  font-weight: 700;
  margin-left: 1.2mm;
}
.meta {
  font-size: 10px;
  margin-top: 1.4mm;
  color: #444;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55mm;
  margin-top: auto;
  width: 100%;
}
img.barcode {
  height: 17mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
